    ["ƒ(utils: FightUtils,unit: UnitEntity, effect: EffectEntity):void=>{const parent = utils.getAncestor(unit);if(parent==undefined){return;}const pPos = parent.getPosition();const angle = effect.s(2);const pos = utils.offsetPoint(pPos,angle + effect.s(0),effect.s(1));unit.setPosition(pos,false);unit.setAngle(angle,0);if(!unit.isSkillRunning('黄金甲/禁军幻影普通攻击')){unit.triggerSkill('黄金甲/禁军幻影普通攻击');}if(effect.activeData.times>=40){unit.kill(unit,undefined,undefined,true);}}"] = function(____, utils, unit, effect)
        local parent = utils:getAncestor(unit)
        if parent == nil then
            return
        end
        local pPos = parent:getPosition()
